private int count = 0;

private void xrTableCell1_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
var parametraRaporti = AlphaWebReports.raporteUtil.DeserializoParametraPerKonstruktorRaporti(this.Extensions["parametraRaporti"]);
  count++;
            xrTableCell1.Text = count.ToString();
            if (GetCurrentColumnValue("KODKLIENTFURNITOR") != null)
            {
                    xrTableCell1.NavigateUrl = "javascript:window.myFaqeCelje.hapFaqeNeTabTeRi('RaportiShpejte.aspx?scopeID="+parametraRaporti.ScopeID+"&guidString=" + parametraRaporti.GuidString+ "&idraporti="+ parametraRaporti.IdSubRaporti+ "&filterFurnitor=" + GetCurrentColumnValue("KODKLIENTFURNITOR") + "&printo=0&Sesioni=true')";
                    xrTableCell1.Target = "_self";
            }
}

